package org.usbworkbench;
import java.io.*;import java.util.*;import java.util.zip.*;
public class TarToolsTest {
 static int checks;static void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}interface A{void run()throws Exception;}static void fails(String code,A a)throws Exception{try{a.run();throw new AssertionError("expected "+code);}catch(IOException e){check(e.getMessage().startsWith(code),e.toString());}}
 static byte[] header(String name,int type,int size)throws Exception{byte[] b=new byte[512];DiskTools.text(b,0,name);DiskTools.text(b,100,"0000644");DiskTools.text(b,124,String.format(Locale.ROOT,"%011o",size));b[156]=(byte)type;DiskTools.text(b,257,"ustar");Arrays.fill(b,148,156,(byte)32);long sum=0;for(byte x:b)sum+=x&255;DiskTools.text(b,148,String.format(Locale.ROOT,"%06o",sum));b[154]=0;b[155]=32;return b;}
 static class Builder {final ByteArrayOutputStream out=new ByteArrayOutputStream();Builder add(String name,int type,byte[] data)throws Exception{out.write(header(name,type,data.length));out.write(data);out.write(new byte[(512-data.length%512)%512]);return this;}byte[] end()throws Exception{out.write(new byte[1024]);return out.toByteArray();}}
 static class Sink implements ZipTools.Sink {final Map<String,ByteArrayOutputStream> files=new HashMap<>();final Set<String> dirs=new HashSet<>();public void directory(String p){dirs.add(p);}public OutputStream file(String p){ByteArrayOutputStream b=new ByteArrayOutputStream();files.put(p,b);return b;}}
 static long extract(byte[] bytes,Sink sink,long limit,int count)throws Exception{return TarTools.extract(new ByteArrayInputStream(bytes),sink,limit,count,(a,b)->{});}
 public static void main(String[] args)throws Exception{
  byte[] payload="hello".getBytes("UTF-8");byte[] tar=new Builder().add("./folder/",'5',new byte[0]).add("./folder/file.txt",'0',payload).end();Sink sink=new Sink();check(extract(tar,sink,100,10)==5,"expanded size");check(sink.dirs.contains("folder")&&Arrays.equals(sink.files.get("folder/file.txt").toByteArray(),payload),"content and paths");
  ByteArrayOutputStream gz=new ByteArrayOutputStream();try(GZIPOutputStream out=new GZIPOutputStream(gz)){out.write(tar);}check(extract(gz.toByteArray(),new Sink(),100,10)==5,"gzip");byte[] corrupt=tar.clone();corrupt[1]^=1;fails("TAR_CHECKSUM",()->extract(corrupt,new Sink(),100,10));
  ByteArrayOutputStream xz=new ByteArrayOutputStream();try(org.tukaani.xz.XZOutputStream out=new org.tukaani.xz.XZOutputStream(xz,new org.tukaani.xz.LZMA2Options(1))){out.write(tar);}check(extract(xz.toByteArray(),new Sink(),100,10)==5,"XZ autodetection and content");byte[] badXz=xz.toByteArray();badXz[badXz.length-4]^=1;try{extract(badXz,new Sink(),100,10);throw new AssertionError("bad XZ accepted");}catch(IOException e){check(true,"XZ footer integrity");}
  for(String path:new String[]{"../escape","/absolute","dir//empty","C:/evil","a/../../b"}){byte[] data=new Builder().add(path,'0',payload).end();fails("TAR_PATH",()->extract(data,new Sink(),100,10));}
  for(int type:new int[]{'1','2','3','4','6','S'}){byte[] data=new Builder().add("unsafe",type,new byte[0]).end();fails("TAR_LINK",()->extract(data,new Sink(),100,10));}
  byte[] duplicate=new Builder().add("FILE",'0',payload).add("file",'0',payload).end();fails("TAR_DUPLICATE",()->extract(duplicate,new Sink(),100,10));fails("TAR_LIMIT",()->extract(tar,new Sink(),4,10));fails("TAR_LIMIT",()->extract(tar,new Sink(),100,1));
  byte[] shortData=new byte[514];System.arraycopy(header("short",'0',5),0,shortData,0,512);fails("TAR_SHORT",()->extract(shortData,new Sink(),100,10));byte[] trailer=tar.clone();trailer[trailer.length-1]=1;fails("TAR_TRAILING",()->extract(trailer,new Sink(),100,10));
  byte[] extended=new Builder().add("././@LongLink",'L',"a/b/c/long-file.txt\0".getBytes("UTF-8")).add("placeholder",'0',payload).end();sink=new Sink();extract(extended,sink,100,10);check(sink.files.containsKey("a/b/c/long-file.txt"),"GNU longname");
  String pair="path=أرشيف/ملف.txt\n";int length=pair.getBytes("UTF-8").length+3;while(Integer.toString(length).length()+1+pair.getBytes("UTF-8").length!=length)length=Integer.toString(length).length()+1+pair.getBytes("UTF-8").length;byte[] pax=(length+" "+pair).getBytes("UTF-8");byte[] paxTar=new Builder().add("PaxHeader",'x',pax).add("placeholder",'0',payload).end();sink=new Sink();extract(paxTar,sink,100,10);check(sink.files.containsKey("أرشيف/ملف.txt"),"PAX unicode path");
  int[] members={0};try(InputStream in=new FileInputStream("native/sources/ntfs3g.tgz")){int count=TarTools.scan(in,(entry,data)->members[0]++,64L*1024*1024,10000,(a,b)->{});check(count==members[0]&&count>100,"real upstream source TAR scan");}
  System.out.println("PASS: "+checks+" TAR/gzip headers, UTF-8/PAX, longnames, path/link/duplicate/limit/corruption and real-source scan checks");
 }
}
